mapper.select:
SELECT distinct assist.* FROM mes_building_assist assist left join mes_building_task_process process on assist.task_process_id=process.id LEFT JOIN mes_building_assist_number_detail detail on detail.task_process_id = process.id and detail.bool_delete_enum =0 and detail.bool_finish_enum =0
INNER JOIN mes_building_task_number_link link ON link.artifact_task_process_id = detail.task_process_id and link.bool_artifact_report = false and link.bool_delete_enum = 0 and link.artifact_number = detail.number
INNER JOIN mes_building_task_number_link link ON link.assemble_task_process_id = detail.task_process_id and link.bool_assemble_report = false and link.bool_delete_enum = 0 and link.assemble_number = detail.number
WHERE assist.bool_delete_enum = 0
and
( assist.groups_id= #{link.groupId} and assist.process_id in
#{processId}
)
and process.task_id=#{taskId}

SELECT process.task_id 'taskId', assist.id 'assistId', assist.task_process_id 'taskProcessId', assist.groups_id 'groupsId', assist.quantity 'quantity', assist.produce_quantity 'produceQuantity' FROM mes_building_assist assist LEFT JOIN mes_building_task_process process ON process.id = assist.task_process_id AND process.bool_delete_enum = 0 WHERE assist.bool_delete_enum = 0
AND process.task_id IN
#{id}

select orde.id as 'id', orde.order_number, pro.ask_complete_time, cp.id 'project.id', cp.`name` 'project.name', cp.short_name 'project.short_name', cp.serial_number 'project.serial_number', ass.groups_id 'assistGroupId', IFNULL(sum(ass.quantity), 0) quantity, IFNULL(sum(ass.produce_quantity), 0) completeQuantity from mes_building_assist ass left join mes_building_task_process pro on ass.task_process_id = pro.id left join mes_building_task_order orde on pro.task_order_id = orde.id left join contract_project cp on pro.project_id = cp.id
ass.quantity != ass.produce_quantity
and ass.process_id = #{processId}
and ass.groups_id in
#{groupId}
group by orde.id, orde.order_number, pro.ask_complete_time, cp.id , cp.`name`, cp.short_name, cp.serial_number, ass.groups_id

select ass.id, ass.task_process_id, ass.groups_id, ass.production_line_id, sum(ass.quantity) quantity, sum(ass.produce_quantity) produceQuantity, ass.process_id, pro.project_id from mes_building_assist ass left join mes_building_task_process pro on ass.task_process_id = pro.id left join mes_building_team team on ass.team_id = team.id and pro.process_id = team.process_id left join mes_building_team_user_link tulink on team.id = tulink.team_id where ass.bool_delete_enum = 0 and pro.bool_delete_enum = 0 and tulink.bool_delete_enum = 0 and tulink.user_id = #{userId} and ass.quantity != ass.produce_quantity
and ass.process_id = #{processId}
GROUP BY ass.id, ass.task_process_id, ass.groups_id, ass.quantity, ass.process_id, pro.project_id

SELECT distinct assist.* FROM mes_building_assist assist left join mes_building_task_process process on assist.task_process_id=process.id LEFT JOIN mes_building_assist_number_detail detail on detail.task_process_id = process.id and detail.bool_delete_enum =0 and detail.bool_finish_enum =0
INNER JOIN mes_building_task_number_link link ON link.artifact_task_process_id = detail.task_process_id and link.bool_artifact_report = false and link.bool_delete_enum = 0 and link.artifact_number = detail.number
INNER JOIN mes_building_task_number_link link ON link.assemble_task_process_id = detail.task_process_id and link.bool_assemble_report = false and link.bool_delete_enum = 0 and link.assemble_number = detail.number
WHERE assist.bool_delete_enum = 0
and
( assist.production_line_id= #{lineProcessLink.lineId} and assist.team_id= #{lineProcessLink.teamId} and assist.process_id in
#{processId}
)
and process.task_id=#{taskId}

select orde.id as 'id', orde.order_number, pro.ask_complete_time, cp.id 'project.id', cp.`name` 'project.name', cp.short_name 'project.short_name', cp.serial_number 'project.serial_number', ass.production_line_id 'assistGroupId', ass.production_line_id 'assistLineId', COUNT(distinct detail.number) AS quantity, IFNULL(sum(ass.produce_quantity), 0) completeQuantity from mes_building_assist ass left join mes_building_task_process pro on ass.task_process_id = pro.id LEFT JOIN mes_building_assist_number_detail detail on detail.task_process_id = pro.id and detail.bool_delete_enum =0 and detail.bool_finish_enum =0
INNER JOIN mes_building_task_number_link link ON link.artifact_task_process_id = detail.task_process_id and link.bool_artifact_report = false and link.bool_delete_enum = 0 and link.artifact_number = detail.number
INNER JOIN mes_building_task_number_link link ON link.assemble_task_process_id = detail.task_process_id and link.bool_assemble_report = false and link.bool_delete_enum = 0 and link.assemble_number = detail.number
left join mes_building_task_order orde on pro.task_order_id = orde.id left join contract_project cp on pro.project_id = cp.id
ass.quantity != ass.produce_quantity and pro.task_type_enum = #{taskTypeEnum}
and ass.process_id = #{processId}
and ass.production_line_id in
#{producLineId}
and cp.id in
#{projectId}
group by orde.id, orde.order_number, pro.ask_complete_time, cp.id , cp.`name`, cp.short_name, cp.serial_number, ass.production_line_id

select distinct assist.*
from mes_building_assist assist
LEFT JOIN mes_building_task_process process on process.id = assist.task_process_id and process.bool_delete_enum =0

    left join tech_artifact ta on process.product_id = ta.id and ta.bool_delete_enum = 0


    left join tech_assemble  ta on process.product_id = ta.id and ta.bool_delete_enum = 0

where assist.bool_delete_enum = 0

    and ta.structure_class_id = #{dtoParam.typeId}


    and ta.assemble_config_id =#{dtoParam.typeId}

and process.task_type_enum = #{dtoParam.productType} and assist.bool_finish_enum = 0 and assist.bool_delete_enum =0
and assist.production_line_id = #{dtoParam.lineId}
and assist.process_id in

    #{processId}
